        "code": "#!/usr/bin/env bash\nset -euo pipefail\n\n# 1. Khoi chay llama-server voi GGUF muc Q6_K (giu do chinh xac Tool Calling >= 94%)\n# -ngl 38: Day 38 lop len GPU 12-16GB VRAM, cac lop con lai chay tren RAM CPU DDR5\n# -c 32768 -np 4: Cap 8,192 token ngu canh cho MOI khe trong 4 khe song song\n./build/bin/llama-server \\\n  --model /models/qwen2.5-14b-instruct-q6_k.gguf \\\n  --alias domation-erp-tool-14b \\\n  --host 127.0.0.1 \\\n  --port 8081 \\\n  --api-key \"${LLAMA_SERVER_API_KEY}\" \\\n  -ngl 38 \\\n  -c 32768 \\\n  -np 4 \\\n  --threads 12 \\\n  -fa on \\\n  --cache-type-k q8_0 \\\n  --cache-type-v q8_0 \\\n  --jinja \\\n  --mlock\n\n# 2. Kiem thu goi Tool Calling + ep khuon JSON Schema nghiem ngat qua OpenAI endpoint:\ncurl -s http://127.0.0.1:8081/v1/chat/completions \\\n  -H \"Content-Type: application/json\" \\\n  -H \"Authorization: Bearer ${LLAMA_SERVER_API_KEY}\" \\\n  -d '{\n    \"model\": \"domation-erp-tool-14b\",\n    \"temperature\": 0.0,\n    \"messages\": [\n      {\"role\": \"user\", \"content\": \"Tao phieu dat coc can E2-12A tri gia 50 trieu cho khach Nguyen Van A, dai ly Tung Long.\"}\n    ],\n    \"tools\": [{\n      \"type\": \"function\",\n      \"function\": {\n        \"name\": \"create_crm_booking\",\n        \"description\": \"Tao booking dat coc can ho trong CRM 360\",\n        \"parameters\": {\n          \"type\": \"object\",\n          \"required\": [\"unit_code\", \"deposit_vnd\", \"agency_f1\"],\n          \"properties\": {\n            \"unit_code\": {\"type\": \"string\"},\n            \"deposit_vnd\": {\"type\": \"integer\"},\n            \"agency_f1\": {\"type\": \"string\", \"enum\": [\"TUNG_LONG\", \"HOP_NHAT\", \"IHD\"]}\n          }\n        }\n      }\n    }]\n  }'"
