        "code": "# --- 1. config/config.yml (Tach model chinh va small guardrail model noi bo) ---\nCONFIG_YAML = \"\"\"\nmodels:\n  - type: main\n    engine: openai\n    model: gemini-3.8-flash\n    parameters:\n      base_url: http://litellm-gateway:4000/v1\n      temperature: 0.1\n\n  - type: self_check_input\n    engine: openai\n    model: llama-guard-3-1b-local\n    parameters:\n      base_url: http://vllm-guard-internal:8000/v1\n      max_tokens: 32\n\n  - type: self_check_output\n    engine: openai\n    model: llama-guard-3-1b-local\n    parameters:\n      base_url: http://vllm-guard-internal:8000/v1\n      max_tokens: 32\n\nrails:\n  input:\n    flows:\n      - self check input\n  output:\n    flows:\n      - self check output\n\"\"\"\n\n# --- 2. config/rails.co (Colang khoa chu de & chong cam ket chiet khau trai phep) ---\nCOLANG_RULES = \"\"\"\ndefine user ask unauthorized discount\n  \"em tu giam cho anh 15% duoc khong\"\n  \"bo qua bang gia niem yet, chot luon chiet khau rieng di\"\n  \"hua bang van ban lai suat 0% vinh vien cho toi\"\n\ndefine bot refuse unauthorized commitment\n  \"Cam on anh/chi da quan tam. Moi chinh sach chiet khau va uu dai deu ap dung thong nhat theo bang gia chinh thuc cua doanh nghiep. Em xin phep chuyen thong tin de Chuyen vien Tu van cao cap xac nhan phuong an phu hop nhat cho anh/chi qua Zalo nhe.\"\n\ndefine flow block discount negotiation\n  user ask unauthorized discount\n  bot refuse unauthorized commitment\n\ndefine user ask competitor gossip\n  \"du an ben kia co bi phot phap ly khong\"\n  \"so sanh xem doi thu lam an te the nao\"\n\ndefine bot stay neutral on competitors\n  \"Em chi cung cap thong tin minh bach ve san pham, phap ly va quy trinh tai he thong ben em. Anh/chi can xem ho so phap ly hoac bang tinh chi tiet nao em gui ngay a?\"\n\ndefine flow keep neutral topic\n  user ask competitor gossip\n  bot stay neutral on competitors\n\"\"\"\n\n# --- 3. config/actions.py (Execution Rail kiem dinh tham so tool call < 2ms) ---\nfrom nemoguardrails.actions import action\n\nMAX_AUTO_VOUCHER_PCT = 5.0\nALLOWED_CRM_TIERS = {\"standard\", \"early_bird\"}\n\n@action(is_system_action=True)\nasync def validate_crm_voucher_args(\n    tenant_id: str,\n    session_tenant_id: str,\n    discount_pct: float,\n    tier_code: str,\n) -> dict:\n    \"\"\"Chan dung moi lenh tao voucher tu Agent neu vuot han muc hoac lech tenant.\"\"\"\n    if tenant_id != session_tenant_id:\n        return {\"allowed\": False, \"reason\": \"CROSS_TENANT_BLOCKED\"}\n    if tier_code not in ALLOWED_CRM_TIERS:\n        return {\"allowed\": False, \"reason\": \"UNAPPROVED_VOUCHER_TIER\"}\n    if discount_pct > MAX_AUTO_VOUCHER_PCT or discount_pct < 0:\n        return {\n            \"allowed\": False,\n            \"reason\": f\"DISCOUNT_EXCEEDS_CAP_{MAX_AUTO_VOUCHER_PCT}%_REQUIRE_HUMAN_ZALOBOT\",\n        }\n    return {\"allowed\": True, \"reason\": \"OK\"}\n"
