        "language": "python",
        "filename": "litellm_presidio_guardrail.py",
        "description": "Minh họa trực tiếp cách thay thế cụm `scan_prompt([Anonymize, Secrets, BanSubstrings])` của protectai/llm-guard bằng CustomGuardrail hook tích hợp sẵn trong LiteLLM proxy: dùng Presidio để che PII và regex tất định để chặn rò rỉ khóa bí mật trước khi request rời VPC.",
        "code": "# TRUOC DAY (DEPRECATING / ARCHIVED 09-07-2026):\n# from llm_guard.vault import Vault\n# from llm_guard.input_scanners import Anonymize, Secrets, PromptInjection\n# sanitized_prompt, results_valid, _ = scan_prompt(scanners, raw_prompt)\n\n# HIEN TAI (THAY THE AN TOAN: Presidio MIT + LiteLLM Custom Guardrail Hook)\nimport re\nfrom typing import Any, Literal\nfrom presidio_analyzer import AnalyzerEngine, Pattern, PatternRecognizer\nfrom presidio_anonymizer import AnonymizerEngine\nfrom presidio_anonymizer.entities import OperatorConfig\nfrom litellm.integrations.custom_guardrail import CustomGuardrail\n\nSECRET_PATTERNS = [\n    re.compile(r\"sk-(?:proj-|ant-)?[A-Za-z0-9_-]{24,}\"),\n    re.compile(r\"AIza[0-9A-Za-z_-]{35}\"),\n    re.compile(r\"-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----\"),\n]\n\n\ndef build_vn_presidio_engines():\n    analyzer = AnalyzerEngine()\n    vn_phone_pattern = Pattern(\n        name=\"vn_phone\",\n        regex=r\"(?:\\+?84|0)(?:3[2-9]|5[25689]|7[06-9]|8[1-9]|9[0-9])[\\s.-]?\\d{3}[\\s.-]?\\d{4}\",\n        score=0.75,\n    )\n    analyzer.registry.add_recognizer(\n        PatternRecognizer(\n            supported_entity=\"VN_PHONE_NUMBER\",\n            patterns=[vn_phone_pattern],\n            context=[\"sdt\", \"dien thoai\", \"zalo\", \"hotline\", \"lien he\"],\n        )\n    )\n    return analyzer, AnonymizerEngine()\n\n\nclass DomationPresidioGuardrail(CustomGuardrail):\n    def __init__(self, **kwargs):\n        super().__init__(**kwargs)\n        self.analyzer, self.anonymizer = build_vn_presidio_engines()\n\n    async def async_pre_call_hook(\n        self,\n        user_api_key_dict: Any,\n        cache: Any,\n        data: dict,\n        call_type: Literal[\"completion\", \"acompletion\", \"embeddings\"],\n    ) -> dict:\n        messages = data.get(\"messages\", [])\n        for msg in messages:\n            content = msg.get(\"content\")\n            if not isinstance(content, str):\n                continue\n            # 1. Chan ro ri khoa bi mat / private key truoc khi roi khoi VPC\n            for pat in SECRET_PATTERNS:\n                if pat.search(content):\n                    raise ValueError(\"Blocked: Secret/API Key detected in prompt payload.\")\n            # 2. Che PII Viet Nam qua data-privacy-stack/presidio\n            results = self.analyzer.analyze(\n                text=content,\n                entities=[\"VN_PHONE_NUMBER\", \"EMAIL_ADDRESS\", \"CREDIT_CARD\"],\n                language=\"en\",\n            )\n            if results:\n                anonymized = self.anonymizer.anonymize(\n                    text=content,\n                    analyzer_results=results,\n                    operators={\"DEFAULT\": OperatorConfig(\"replace\", {\"new_value\": \"<PII_REDACTED>\"})},\n                )\n                msg[\"content\"] = anonymized.text\n        return data\n"
